    value_types: TypesNames = [
        t if isinstance(t, str) else getattr(t, "__name__", type(t).__name__).lower()
        for t in value_types
        # avoid recursion
        if t not in ["iterable", "list", "tuple", "dict", "set"]
    ]
    if not value_types:
        value_types = self.default_value_types  # type: ignore

