    # NOTE: On windows, the lowest value you can get from windows is 86400
    #       on the first day. Known python issue:
    #       https://bugs.python.org/issue30684
    return datetime(1970, 1, 1, tzinfo=tzinfo) + timedelta(seconds=ts)

